import { Router } from "express";
import * as cheerio from "cheerio";

export const linkPreviewRouter = Router();

linkPreviewRouter.get("/api/link-preview", async (req, res) => {
  const target = String(req.query.url ?? "");
  if (!target.startsWith("http")) {
    return res.status(400).json({ error: "url must be http(s)" });
  }
  const response = await fetch(target, { redirect: "follow" });
  const html = await response.text();
  const $ = cheerio.load(html);
  res.json({
    title: $("meta[property='og:title']").attr("content") ?? $("title").text(),
    description: $("meta[property='og:description']").attr("content") ?? null,
    image: $("meta[property='og:image']").attr("content") ?? null,
  });
});

import { NextResponse } from "next/server";
import Parser from "rss-parser";

const parser = new Parser();

export async function POST(request: Request) {
  const { feedUrl } = await request.json();
  const res = await fetch(feedUrl, { headers: { Accept: "application/rss+xml" } });
  if (!res.ok) {
    return NextResponse.json({ error: `Feed returned ${res.status}` }, { status: 502 });
  }
  const feed = await parser.parseString(await res.text());
  return NextResponse.json({ title: feed.title, items: feed.items.slice(0, 20) });
}

