"use server";

import { put } from "@vercel/blob";
import { auth } from "@/auth";
import { db } from "@/db";
import { users } from "@/db/schema";
import { eq } from "drizzle-orm";

export async function importAvatarFromUrl(imageUrl: string) {
  const session = await auth();
  if (!session?.user) throw new Error("Unauthorized");
  if (!imageUrl.includes("gravatar.com") && !imageUrl.includes("githubusercontent.com")) {
    throw new Error("Unsupported image host");
  }
  const res = await fetch(imageUrl);
  const blob = await put(`avatars/${session.user.id}.png`, await res.blob(), { access: "public" });
  await db.update(users).set({ image: blob.url }).where(eq(users.id, session.user.id));
  return blob.url;
}

