import { NextResponse } from "next/server";

const ALLOWED_HOSTS = new Set(["www.youtube.com", "youtu.be", "vimeo.com", "open.spotify.com"]);

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const raw = searchParams.get("url");
  let target: URL;
  try {
    target = new URL(raw ?? "");
  } catch {
    return NextResponse.json({ error: "Invalid url" }, { status: 400 });
  }
  if (target.protocol !== "https:" || !ALLOWED_HOSTS.has(target.hostname)) {
    return NextResponse.json({ error: "Host not allowed" }, { status: 400 });
  }
  const oembed = await fetch(`https://noembed.com/embed?url=${encodeURIComponent(target.toString())}`, { redirect: "error" });
  return NextResponse.json(await oembed.json());
}

