import { Router } from "express";
import multer from "multer";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { writeFile } from "node:fs/promises";

const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 2 * 1024 * 1024 } });
export const avatarsRouter = Router();

avatarsRouter.post("/avatars", upload.single("avatar"), async (req, res) => {
  if (!req.file) return res.status(400).json({ error: "missing file" });
  const ext = path.extname(req.file.originalname).toLowerCase();
  if (![".png", ".jpg", ".jpeg", ".webp"].includes(ext)) return res.status(415).end();
  const name = `${randomUUID()}${ext}`;
  await writeFile(path.join(process.cwd(), "uploads", "avatars", name), req.file.buffer);
  res.status(201).json({ url: `/avatars/${name}` });
});

