import { Router, raw } from "express";
import { createHmac, timingSafeEqual } from "node:crypto";

export const githubWebhook = Router();

githubWebhook.post("/webhooks/github", raw({ type: "application/json" }), (req, res) => {
  const expected = "sha256=" + createHmac("sha256", process.env.GITHUB_WEBHOOK_SECRET!).update(req.body).digest("hex");
